import{_ as r,C as i,o as n,c as d,j as l,a,E as o,w as t,a3 as c}from"./chunks/framework.EDt1A0Ag.js";const f=JSON.parse('{"title":"Clash Verge Rev 完整保姆级使用教程 2026【新手图文从入门到精通】","description":"2026年最新Clash Verge Rev完整保姆级图文教程。从官方安全下载、中文语言切换、导入机场订阅链接、开启系统代理与TUN虚拟网卡模式，到规则分流配置与常见报错排查全解。","frontmatter":{"title":"Clash Verge Rev 完整保姆级使用教程 2026【新手图文从入门到精通】","description":"2026年最新Clash Verge Rev完整保姆级图文教程。从官方安全下载、中文语言切换、导入机场订阅链接、开启系统代理与TUN虚拟网卡模式，到规则分流配置与常见报错排查全解。"},"headers":[],"relativePath":"client/clash-verge.md","filePath":"client/clash-verge.md","lastUpdated":1787499481000}'),g={name:"client/clash-verge.md"},h={class:"flex items-center gap-2 mb-6"};function p(u,e,m,b,v,C){const s=i("LeafBadge");return n(),d("div",null,[e[4]||(e[4]=l("h1",{id:"🚀-clash-verge-rev-完整保姆级使用教程-2026",tabindex:"-1"},[a("🚀 Clash Verge Rev 完整保姆级使用教程 2026 "),l("a",{class:"header-anchor",href:"#🚀-clash-verge-rev-完整保姆级使用教程-2026","aria-label":'Permalink to "🚀 Clash Verge Rev 完整保姆级使用教程 2026"'},"​")],-1)),l("div",h,[o(s,{variant:"primary"},{default:t(()=>[...e[0]||(e[0]=[a("TYPE-C 保姆教程",-1)])]),_:1}),o(s,{variant:"wood"},{default:t(()=>[...e[1]||(e[1]=[a("Windows / Mac / Linux",-1)])]),_:1}),o(s,{variant:"amber"},{default:t(()=>[...e[2]||(e[2]=[a("Mihomo 内核",-1)])]),_:1}),o(s,{variant:"accent"},{default:t(()=>[...e[3]||(e[3]=[a("3500+ 字详解",-1)])]),_:1})]),e[5]||(e[5]=c(`<p><strong>Clash Verge Rev</strong> 是目前 Windows、macOS 和 Linux 平台上最受欢迎、维护最活跃的开源代理客户端。它基于现代 Tauri + Vue 3 框架构建，内置强大的 <strong>Mihomo (原 Clash Meta) 内核</strong>，原生支持 <strong>VLESS (Reality)、Shadowsocks 2022、Hysteria2、TUIC</strong> 等新一代协议，并拥有一键开启 TUN 虚拟网卡模式的卓越能力。</p><hr><h2 id="🎯-学习目标与准备工作" tabindex="-1">🎯 学习目标与准备工作 <a class="header-anchor" href="#🎯-学习目标与准备工作" aria-label="Permalink to &quot;🎯 学习目标与准备工作&quot;">​</a></h2><h3 id="_1-本文学习目标" tabindex="-1">1. 本文学习目标 <a class="header-anchor" href="#_1-本文学习目标" aria-label="Permalink to &quot;1. 本文学习目标&quot;">​</a></h3><ul><li>掌握 Clash Verge Rev 的官方安全下载与安装流程；</li><li>掌握如何将机场订阅链接一键导入客户端并完成节点更新；</li><li>理解并掌握三种代理模式（Rule 规则 / Global 全局 / Direct 直连）；</li><li>学会开启 <strong>TUN 虚拟网卡模式</strong>，解决命令行、游戏及部分 UWP 应用不走代理的问题；</li><li>掌握常见报错（如 <code>Fetch Failed</code>、系统代理被篡改、节点全红）的自我排查技能。</li></ul><h3 id="_2-准备工作清单" tabindex="-1">2. 准备工作清单 <a class="header-anchor" href="#_2-准备工作清单" aria-label="Permalink to &quot;2. 准备工作清单&quot;">​</a></h3><ol><li>一台运行 Windows 10/11、macOS (Intel/Apple Silicon) 或 Linux 的电脑；</li><li>任意一家有效运营中的 <a href="/ranking/stable">稳定机场订阅链接</a>（支持 Clash / SSR 格式）；</li><li>畅通的本地网络（确保本地宽带或 Wi-Fi 能正常打开国内网站）。</li></ol><hr><h2 id="🛠️-step-by-step-核心操作步骤" tabindex="-1">🛠️ Step-by-Step 核心操作步骤 <a class="header-anchor" href="#🛠️-step-by-step-核心操作步骤" aria-label="Permalink to &quot;🛠️ Step-by-Step 核心操作步骤&quot;">​</a></h2><h3 id="第一步-下载与安装客户端" tabindex="-1">第一步：下载与安装客户端 <a class="header-anchor" href="#第一步-下载与安装客户端" aria-label="Permalink to &quot;第一步：下载与安装客户端&quot;">​</a></h3><ol><li>前往官方开源仓库 Release 页面下载对应系统的最新版本安装包： <ul><li><strong>Windows 64位系统</strong>：下载 <code>Clash.Verge_x.x.x_x64-setup.exe</code> 或 <code>x64_portable.zip</code>（便携版）；</li><li><strong>Mac Apple 芯片 (M1/M2/M3/M4)</strong>：下载 <code>Clash.Verge_x.x.x_aarch64.dmg</code>；</li><li><strong>Mac Intel 芯片</strong>：下载 <code>Clash.Verge_x.x.x_x64.dmg</code>。</li></ul></li><li>运行安装程序，按照默认提示完成安装并启动软件。</li></ol><h3 id="第二步-切换中文语言界面-如默认非中文" tabindex="-1">第二步：切换中文语言界面（如默认非中文） <a class="header-anchor" href="#第二步-切换中文语言界面-如默认非中文" aria-label="Permalink to &quot;第二步：切换中文语言界面（如默认非中文）&quot;">​</a></h3><ul><li>启动软件后，点击左侧菜单栏底部的 <strong><code>Settings</code> (设置)</strong>；</li><li>在 <code>Verge Settings</code> 区域找到 <strong><code>Language</code> (语言)</strong>，下拉选择 <strong><code>简体中文 (zh-CN)</code></strong>，界面即刻变为全中文。</li></ul><h3 id="第三步-导入机场订阅链接" tabindex="-1">第三步：导入机场订阅链接 <a class="header-anchor" href="#第三步-导入机场订阅链接" aria-label="Permalink to &quot;第三步：导入机场订阅链接&quot;">​</a></h3><ol><li>登录你的机场后台，复制你的 <strong>Clash 订阅链接</strong>（通常是一个以 <code>https://</code> 开头的长链接）；</li><li>打开 Clash Verge Rev，点击左侧菜单栏的 <strong><code>订阅 (Profiles)</code></strong>；</li><li>在顶部输入框中粘贴刚刚复制的订阅 URL，随后点击右侧的 <strong><code>导入 (Import)</code></strong> 按钮；</li><li>等待 2~5 秒，当看到配置卡片显示机场名称及剩余流量/过期时间信息时，<strong>左键点击该卡片选中它</strong>（卡片右侧会出现绿色对勾或高亮边框）。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[复制机场订阅 URL] ──&gt; [粘贴至 Clash Verge 订阅输入框] ──&gt; [点击导入] ──&gt; [左键激活配置]</span></span></code></pre></div><h3 id="第四步-选择节点并开启系统代理" tabindex="-1">第四步：选择节点并开启系统代理 <a class="header-anchor" href="#第四步-选择节点并开启系统代理" aria-label="Permalink to &quot;第四步：选择节点并开启系统代理&quot;">​</a></h3><ol><li>点击左侧菜单栏的 <strong><code>代理 (Proxies)</code></strong> 页面；</li><li>顶部模式选择 <strong><code>规则 (Rule)</code></strong>（⚠️ <strong>极其重要</strong>：切勿选 Direct 或随意选 Global）；</li><li>在 <code>PROXY</code> 或 <code>节点选择</code> 策略组中，展开节点列表，点击你心仪的节点（例如 <em>“🇭🇰 香港 01 [IEPL专线]”</em> 或 <em>“🇺🇸 美国 01 [原生解锁]”</em>）；</li><li>点击右下角或左侧菜单栏的 <strong><code>设置</code></strong>，将 <strong><code>系统代理 (System Proxy)</code></strong> 的开关切换为 <strong>开启 (ON)</strong>。</li><li>打开浏览器，访问 <code>google.com</code> 或 <code>youtube.com</code>，即可享受极速出海体验！</li></ol><hr><h2 id="⚡-核心进阶功能-一键开启-tun-虚拟网卡模式" tabindex="-1">⚡ 核心进阶功能：一键开启 TUN 虚拟网卡模式 <a class="header-anchor" href="#⚡-核心进阶功能-一键开启-tun-虚拟网卡模式" aria-label="Permalink to &quot;⚡ 核心进阶功能：一键开启 TUN 虚拟网卡模式&quot;">​</a></h2><h3 id="什么是-tun-模式-为什么需要它" tabindex="-1">什么是 TUN 模式？为什么需要它？ <a class="header-anchor" href="#什么是-tun-模式-为什么需要它" aria-label="Permalink to &quot;什么是 TUN 模式？为什么需要它？&quot;">​</a></h3><p>普通的“系统代理”仅对支持 HTTP/Socks5 代理协议的浏览器生效。而像 <strong>Git 命令行克隆、Docker 镜像拉取、Telegram 桌面客户端、Epic/Steam 游戏平台</strong> 等软件往往默认忽略系统代理。</p><p>开启 <strong>TUN (虚拟网卡接管模式)</strong> 后，Clash 会在操作系统中虚拟一张专用网卡，将电脑的所有 TCP/UDP 流量无缝接管并按规则分流，真正做到<strong>全局底层加速</strong>。</p><h3 id="开启步骤" tabindex="-1">开启步骤： <a class="header-anchor" href="#开启步骤" aria-label="Permalink to &quot;开启步骤：&quot;">​</a></h3><ol><li>以<strong>管理员身份运行</strong> Clash Verge Rev；</li><li>进入 <strong><code>设置 (Settings)</code></strong> 页面；</li><li>找到 <strong><code>TUN 模式 (Tun Mode)</code></strong>，点击开启开关；</li><li>首次开启系统会提示安装网卡服务驱动，点击“允许/确认安装”；</li><li>看到 TUN 开关变为绿色即表示全系统网卡接管成功！</li></ol><hr><h2 id="🧭-流量分流原理解析-智能规则模式" tabindex="-1">🧭 流量分流原理解析 (智能规则模式) <a class="header-anchor" href="#🧭-流量分流原理解析-智能规则模式" aria-label="Permalink to &quot;🧭 流量分流原理解析 (智能规则模式)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                       ┌─── 访问国内网站 (百度/淘宝/B站) ──────&gt; 【直连 DIRECT (0延迟/不耗流量)】</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>用户发起网络请求 ───────┼─── 访问海外网站 (Google/YouTube/GitHub) ──&gt; 【加速代理 PROXY (走专线节点)】</span></span>
<span class="line"><span>                       │</span></span>
<span class="line"><span>                       └─── 访问 AI 与流媒体 (ChatGPT/Netflix) ──&gt; 【专用原生解锁节点】</span></span></code></pre></div><hr><h2 id="❓-clash-verge-rev-高频故障与-faq-排查-10条必备解答" tabindex="-1">❓ Clash Verge Rev 高频故障与 FAQ 排查 (10条必备解答) <a class="header-anchor" href="#❓-clash-verge-rev-高频故障与-faq-排查-10条必备解答" aria-label="Permalink to &quot;❓ Clash Verge Rev 高频故障与 FAQ 排查 (10条必备解答)&quot;">​</a></h2><details class="details custom-block"><summary>1. 导入订阅提示 <code>Fetch Failed</code> 或超时怎么办？</summary><p>① 检查订阅链接是否完整复制，前后是否有空格；② 开启前置代理或切换手机热点再次点击更新；③ 部分机场订阅域名被污染，可在机场后台复制“备用订阅链接”或“Base64 订阅链接”。</p></details><details class="details custom-block"><summary>2. 开启系统代理后国内微信能发消息，但百度打不开？</summary><p>这是本地 DNS 冲突导致的。进入 Clash Verge 设置，将 DNS 模式由 <code>redir-host</code> 修改为 <code>fake-ip</code>，并点击右上角重启内核。</p></details><details class="details custom-block"><summary>3. 为什么节点测速全部显示 Timeout（全红）？</summary><p>① 检查电脑系统时间是否准确（请在 Windows 设置中点击“立即同步时间”）；② 确认机场套餐是否已到期或流量已用尽；③ 检查是否开启了其他杀毒软件的防火墙拦截。</p></details><details class="details custom-block"><summary>4. 退出软件后电脑突然完全无法上网（网页打不开）？</summary><p>这是由于软件异常退出导致 Windows 系统代理未正常关闭。<strong>解决方法</strong>：打开 Windows <code>设置 &gt; 网络和 Internet &gt; 代理</code>，将“使用代理服务器”手动关闭即可立即恢复。</p></details><details class="details custom-block"><summary>5. 如何设置开机自启并静默运行？</summary><p>进入 Clash Verge <code>设置</code>，勾选 <strong><code>开机自启 (Launch on Boot)</code></strong> 与 <strong><code>静默启动 (Silent Start)</code></strong> 两个开关。</p></details><details class="details custom-block"><summary>6. 规则模式 (Rule) 与 全局模式 (Global) 选哪个？</summary><p>日常使用 <strong>100% 推荐使用规则模式 (Rule)</strong>。只有在极少数特定国外软件无法被规则命中识别时，才临时切换为全局模式。</p></details><details class="details custom-block"><summary>7. Clash Verge Rev 和已经停更的原版 Clash for Windows 有什么区别？</summary><p>原版 Clash for Windows 早在 2023 年底停止维护；Clash Verge Rev 是完全基于开源社区重构的现代化替代品，采用最新的 Mihomo 内核，修复了所有已知安全漏洞，支持最新的 VLESS Reality 与 Hysteria2 协议。</p></details><details class="details custom-block"><summary>8. 如何在不同节点策略组之间自动优选最低延迟？</summary><p>在代理面板中，找到名为 <strong><code>AUTO</code></strong> 或 <strong><code>自动选择 (URL-Test)</code></strong> 的策略组并选中它。客户端每隔 5~10 分钟会自动向 Google 发起轻量 Ping 测速，始终为你连接延迟最低的节点。</p></details><details class="details custom-block"><summary>9. 使用 Clash 会影响玩国服《英雄联盟》或《原神》吗？</summary><p>在 <strong>规则模式 (Rule)</strong> 下完全不影响。所有国服游戏服务器 IP 均在内置的直连白名单中，游戏数据包直接走本地宽带直连，ping 值与关闭软件时完全一致。</p></details><details class="details custom-block"><summary>10. 如何彻底卸载 Clash Verge Rev？</summary><p>在控制面板中卸载软件后，手动删除用户目录下的配置文件夹 <code>C:\\Users\\你的用户名\\.config\\clash-verge</code> 即可彻底清除所有缓存与配置。</p></details>`,40))])}const k=r(g,[["render",p]]);export{f as __pageData,k as default};
